        return False

    # Check if Alice is to the right of Peter
    if solution[0][0] < solution[1][0]:
        return False

    # Check if the person who paints is two houses away from the person with average height
    if solution[0][2] == 'painting' and abs(solution[0][0] - solution[1][0]) != 2:
        return False

    # Check if Peter is to the left of the person who loves cooking
    if solution[0][0] >= solution[1][0]:
        return False

    # Check if the person who is tall and Alice are next to each other
    if solution[0][2] == 'tall' and solution[0][1] != 'Alice' or solution[1][2] == 'tall' and solution[1][1] != 'Alice':
        return False

