    if abs(solution[0][0] - solution[1][0]) != 1 or solution[0][2] != 'photography' or solution[1][2] != 'gardening':
        return False

    # Check if the person who loves cooking is not in the third house
    if solution[0][0] == 3:
        return False

    return True

# Function to find the solution
